public CommandFailure? RecordExport(long expectedRevision, Uuid exportId,
    int populationVersion, string format, string fileName, Uuid artifactId,
    string outputContentSha256, long outputContentLength,
    Uuid actorMemberId, string actorDisplay, DateTimeOffset generatedAt)
{
    if (_current is not { } current)
        return CommandFailure.MissingRecord("The audit population was not found.");
    format = Clean(format).ToLowerInvariant();
    fileName = Clean(fileName);
    if (current.Exports.FirstOrDefault(item => item.ExportId == exportId) is { } existing)
        return existing.PopulationVersion == populationVersion && existing.Format == format &&
            existing.FileName == fileName && existing.ArtifactId == artifactId &&
            existing.OutputContentSha256 == outputContentSha256 &&
            existing.OutputContentLength == outputContentLength ? null :
            CommandFailure.StateConflict("An export identity cannot be reused for different population content.");
    if (expectedRevision != Revision)
        return StaleRevision();
    var version = current.Versions.FirstOrDefault(item => item.Version == populationVersion);
    if (current.Status is not ("frozen" or "amending" or "reconciled") || version is null ||
        !ExportFormats.Contains(format) ||
        exportId == Uuid.Empty || artifactId == Uuid.Empty || !IsHash(outputContentSha256) ||
        outputContentLength <= 0 || !Bounded(fileName, 1, 255) ||
        fileName.Contains('/') || fileName.Contains('\\') ||
        !ValidActor(actorMemberId, actorDisplay, generatedAt) || generatedAt < current.UpdatedAt ||
        current.Exports.Count >= MaximumExports)
        return Invalid("Population export requires an exact frozen version, supported format, stable identity, and attribution.");
    var export = new AuditPopulationExportView(exportId, populationVersion, format, fileName,
        version.ContentSha256, version.CloseSnapshotId, generatedAt, actorMemberId, actorDisplay.Trim(),
        artifactId, outputContentSha256, outputContentLength);
    var state = current with
    {
        Revision = Revision + 1,
        Exports = Append(current.Exports, export),
        ActorMemberId = actorMemberId,
        ActorDisplay = actorDisplay.Trim(),
        UpdatedAt = generatedAt,
    };
    return Emit(state, actorMemberId, generatedAt,
        static (tenant, subject, revision, actor, snapshot, at) =>
            new AuditPopulationExportGenerated(tenant, subject, revision, actor, snapshot, at),
        "export");

On<ProviderCoverageGapRecorded>(recorded =>
{
    Acceptance.Observe(recorded);
    if (_recorded is not null || recorded.TenantId != _tenantId || recorded.ProviderId != _providerId ||
        recorded.GapId != _gapId || recorded.ProviderRevision < 1 || recorded.Operation.Owner != Stream ||
        recorded.Operation.LogicalId != _gapId || recorded.RequestId != _gapId)
        throw new InvalidOperationException("A gap is recorded once, by its own provider and logical identity.");
    _recorded = recorded;
    _revision = 1;
});
On<ProviderCoverageGapClosed>(closed =>
{
    Acceptance.Observe(closed);
    if (_recorded is null || _closed is not null || closed.TenantId != _tenantId ||
        closed.ProviderId != _providerId || closed.GapId != _gapId || closed.Revision != _revision + 1 ||
        closed.Operation.Owner != Stream || closed.Operation.LogicalId != closed.RequestId)
        throw new InvalidOperationException("A closure must follow the open gap and its previous revision.");
    _closed = closed;
    _revision = closed.Revision;
});
On<ProviderCoverageGapRiskAcceptanceAdmitted>(admitted =>
{
    Acceptance.Observe(admitted);
    if (_recorded is null || _closed is not null || admitted.Owner != Stream ||
        admitted.Revision != _revision + 1 || admitted.Operation.Owner != Stream ||
        !_admittedPairs.Add(admitted.Operation.Episode) ||
        !_admissions.TryAdd(admitted.Operation.LogicalId, admitted))
        throw new InvalidOperationException(
            "A risk acceptance link is admitted on the open gap for a new pair at the next revision.");
    _revision = admitted.Revision;

public Result PrepareClose(long expectedRevision, ProviderCoverageGapContent recorded,
    ProviderCoverageGapClosureContent closure)
{
    ArgumentNullException.ThrowIfNull(recorded);
    ArgumentNullException.ThrowIfNull(closure);
    if (_recorded is null)
        return Result.Failure(new RequestError(RequestErrorKind.NotFound, "The provider coverage gap was not found."));
    if (expectedRevision != _revision)
        return Result.Failure(VersionedRecordRules.StaleRevision("provider coverage gap", _revision)
            .ToRequestError());
    if (_closed is not null)
        return Result.Failure(new RequestError(RequestErrorKind.Conflict,
            "A provider coverage gap can be closed only once."));
    return recorded.SourceKind == closure.SourceKind && recorded.SourceId == closure.SourceId &&
           closure.SourceRevision <= recorded.SourceRevision
        ? Result.Failure(new RequestError(RequestErrorKind.Validation,
            "A provider coverage gap requires a newer or different closure source."))
        : Result.Success;
}

/// <summary>Accepts the closure as the native fact of its logical command.</summary>
public Result Close(OperationProvenance operation, long expectedRevision, ProviderCoverageGapContent recorded,
    ProviderCoverageGapClosureContent closure, ImmutableContentRef content, ActorReference actor,
    DateTimeOffset closedAt, ImmutableContentRef firstResponse, ImmutableContentRef operationResult)
{
    ArgumentNullException.ThrowIfNull(operation);
    if (operation.LogicalId == Uuid.Empty || operation.Owner != Stream)
        return Result.Failure(new RequestError(RequestErrorKind.Validation,
            "A gap closure requires its own logical operation."));
    var prepared = PrepareClose(expectedRevision, recorded, closure);
    if (!prepared.IsSuccess)
        return prepared;
    RaiseEvent(new ProviderCoverageGapClosed(_tenantId, _gapId, _providerId, operation.LogicalId, _revision + 1,
        content, actor, closedAt, operation, firstResponse, operationResult));

public Result PrepareAdmitLink(long expectedRevision, Uuid riskId, Uuid acceptanceId)
{
    if (_recorded is null)
        return Result.Failure(new RequestError(RequestErrorKind.NotFound, "The provider coverage gap was not found."));
    if (expectedRevision != _revision)
        return Result.Failure(VersionedRecordRules.StaleRevision("provider coverage gap", _revision)
            .ToRequestError());
    if (_closed is not null)
        return Result.Failure(new RequestError(RequestErrorKind.Conflict,
            "A closed provider coverage gap cannot receive a risk acceptance link."));
    return _admittedPairs.Contains(PairEpisode(riskId, acceptanceId))
        ? Result.Failure(new RequestError(RequestErrorKind.Conflict,
            "The risk acceptance is already linked to this provider coverage gap."))
        : Result.Success;
}

/// <summary>
///     Admits the link as the root native fact of its logical command. The admission produces the next gap
///     revision, which <paramref name="operation" /> keeps even if the gap closes before the link materializes.
/// </summary>
public Result AdmitLink(OperationProvenance operation, long expectedRevision, Uuid riskId, Uuid acceptanceId,
    ImmutableContentRef intent, ImmutableContentRef firstResponse)
{
    ArgumentNullException.ThrowIfNull(operation);
    ArgumentNullException.ThrowIfNull(intent);
    ArgumentNullException.ThrowIfNull(firstResponse);
    if (operation.LogicalId == Uuid.Empty || operation.Owner != Stream ||
        operation.Episode != PairEpisode(riskId, acceptanceId))
        return Result.Failure(new RequestError(RequestErrorKind.Validation,
            "A link admission is the logical operation of its own gap owner, bound to its pair."));
    var prepared = PrepareAdmitLink(expectedRevision, riskId, acceptanceId);
    if (!prepared.IsSuccess)
        return prepared;
    var revision = _revision + 1;
    RaiseEvent(new ProviderCoverageGapRiskAcceptanceAdmitted(Stream, revision, revision, intent, null, operation,
        firstResponse, null));

var handoff = await handoffs.ReadAsync(request.TenantId, request.ProgramId, request.HandoffId, ct)
    .ConfigureAwait(false);
if (!handoff.IsCreated || handoff.ProgramId != request.ProgramId)
    return Result<Page<AdvisorFeedbackView>>.Failure(new RequestError(
        RequestErrorKind.NotFound,
        "The advisor handoff was not found in the requested program."));

var admitted = handoff.Handoff.Admitted.Select(static fact => fact.Operation.LogicalId).ToArray();
var start = 0;
if (cursorId is { } after)
{
    var cursorIndex = Array.IndexOf(admitted, after);
    if (cursorIndex < 0)
        return Invalid("The advisor feedback cursor is invalid for this handoff.");
    start = cursorIndex + 1;
}

var limit = request.Limit ?? DefaultLimit;
var threads = new List<AdvisorFeedbackThread>(limit + 1);
for (var index = start; index < admitted.Length && threads.Count <= limit; index++)
{
    var thread = await reader.HydrateAsync(new AdvisorFeedbackThread(request.TenantId, request.ProgramId,
        request.HandoffId, admitted[index]), ct).ConfigureAwait(false);
    if (thread.IsMaterialized)
        threads.Add(thread);
}

var hasMore = threads.Count > limit;
var pageThreads = threads.Take(limit).ToArray();
var currentSources = new HashSet<AdvisorRecordVersion>();
foreach (var source in pageThreads.Select(thread => SourceOf(thread.Recorded!))
             .Where(source => handoff.Selection.Contains(source) && source.IsSupported).Distinct())
{
    var current = await versions.RequireCurrentAsync(request.TenantId,
        request.ProgramId, [source], ct).ConfigureAwait(false);
    if (current.IsSuccess)

for (var attempt = 0; attempt < MaximumConcurrencyAttempts; attempt++)
{
    var source = await reader.HydrateAsync(target, ct).ConfigureAwait(false);
    if (!source.IsCreated || !await visibility.CanReadApplicationAsync(request.TenantId,
            userId, request.ApplicationId, ct).ConfigureAwait(false))
        return NotFound();

    var projection = await ApplicationRelationshipProjection.ReadAsync(source,
        request.TenantId, userId, visibility, ct).ConfigureAwait(false);
    if (source.TryGetApplicationRelationship(request.RelationshipId,
            out var existing, out _))
    {
        if (existing is null || !await visibility.CanReadApplicationAsync(
                request.TenantId, userId, existing.TargetApplicationId, ct)
                .ConfigureAwait(false))
            return NotFound();
        if (source.TryResolveApplicationRelationshipAdd(request.RelationshipId,
                request.TargetApplicationId, request.RelationshipType, out var retry))
            return MapVisibleRevision(retry, projection.Revision);
    }
    else if (!await visibility.CanReadApplicationAsync(request.TenantId, userId,
                 request.TargetApplicationId, ct).ConfigureAwait(false))
    {
        return NotFound();
    }

    if (request.ExpectedRelationshipRevision != projection.Revision)
        return Result<ApplicationRelationshipChange>.Failure(
            ApplicationRelationshipConcurrency.VisibleRevisionMismatch(
                request.ExpectedRelationshipRevision, projection.Revision));

    var result = await executor.ExecuteAsync(target, app =>
    {
        if (app.SourceRelationshipRevision != source.SourceRelationshipRevision)
            return AggregateOutcome.Discard(Result<ApplicationRelationshipChange>.Failure(
                ApplicationRelationshipConcurrency.SourceChanged()));
        if (app.TryResolveApplicationRelationshipAdd(request.RelationshipId,
                request.TargetApplicationId, request.RelationshipType, out var retry))
            return AggregateOutcome.Discard(retry);
        return AggregateOutcome.CommitOnSuccess(app.AddApplicationRelationship(
            source.SourceRelationshipRevision, request.RelationshipId,
            request.TargetApplicationId, request.RelationshipType, memberId, display,
            clock.GetUtcNow()));
    }, context, ct).ConfigureAwait(false);
    if (ApplicationRelationshipConcurrency.IsSourceChanged(result.Error))
        continue;
    if (!result.IsSuccess)
        return result;

    var latest = await reader.HydrateAsync(target, ct).ConfigureAwait(false);
    var latestProjection = await ApplicationRelationshipProjection.ReadAsync(latest,
        request.TenantId, userId, visibility, ct).ConfigureAwait(false);
    return MapVisibleRevision(result, latestProjection.Revision);

var bytes = AuditPopulationExportDocument.Build(current, version, format);
var outputSha = Convert.ToHexString(SHA256.HashData(bytes)).ToLowerInvariant();
var fileName = $"audit-population-{request.PopulationId}-v{version.Version}.{format}";
var capturedAt = clock.GetUtcNow();
var metadata = new EvidenceArtifactContent($"Audit population v{version.Version} export",
    $"Deterministic {format.ToUpperInvariant()} export of frozen population {request.PopulationId}, version {version.Version}.",
    "audit_population_export", "Bdgrz audit population", capturedAt,
    definition.Content.PeriodStart, definition.Content.PeriodEnd, "confidential");
var collector = ActorReference.ForMember(actorMemberId, actorDisplay);
